#!/usr/bin/env python3
"""Probe elfcat with files of varying size and e_ident values."""
import subprocess, os, sys

EXE = "/workspace/executable"
D = "/tmp/specwork_cli/matrix"
os.makedirs(D, exist_ok=True)

def make_file(ei_class=1, ei_data=1, ei_version=1, size=64, fill=0):
    buf = bytearray([fill] * max(size, 16))
    buf[0:4] = b"\x7fELF"
    buf[4] = ei_class
    buf[5] = ei_data
    buf[6] = ei_version
    return bytes(buf[:size])

def run(path):
    p = subprocess.run([EXE, path], capture_output=True)
    out = p.stdout.decode("utf-8", "backslashreplace")
    err = p.stderr.decode("utf-8", "backslashreplace")
    return p.returncode, out, err

def probe(tag, **kw):
    path = os.path.join(D, tag)
    with open(path, "wb") as f:
        f.write(make_file(**kw))
    rc, out, err = run(path)
    # normalize pid in panics
    print(f"{tag}: exit={rc}")
    if out: print(f"  stdout: {out!r}")
    if err: print(f"  stderr: {err!r}")

# size sweep for valid 64-bit and 32-bit headers
for cls in (1, 2):
    for size in [16, 17, 31, 32, 33, 51, 52, 53, 63, 64, 65, 119, 120, 121]:
        probe(f"cls{cls}_sz{size}", ei_class=cls, size=size)

# invalid EI_CLASS / EI_DATA / EI_VERSION at full 64-byte size
for v in (0, 3, 255):
    probe(f"ei_class_{v}", ei_class=v, size=64)
for v in (0, 3, 255):
    probe(f"ei_data_{v}", ei_data=v, size=64)
for v in (0, 2):
    probe(f"ei_version_{v}", ei_version=v, size=64)
